draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Draw book
  ctx.fillStyle = '#663300';
  ctx.fillRect(W/2-50, H/2-75, 100, 150);
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.strokeRect(W/2-50, H/2-75, 100, 150);

  // Draw stick figure
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2-200, 25, 0, 2 * Math.PI);
  ctx.fill();
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-175);
  ctx.lineTo(W/2, H/2-100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-150);
  ctx.lineTo(W/2-50, H/2-100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-150);
  ctx.lineTo(W/2+50, H/2-100);
  ctx.stroke();

  // Draw wisdom symbols
  ctx.fillStyle = 'black';
  ctx.font = '30px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('?', W/2, H/2-50 + 25 * Math.sin(t));

  // Draw lesson life applying
  ctx.font = '20px Arial';
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.fillText('Apply', W/2-75, H/2+50 + 10 * Math.cos(t));
  ctx.fillText('Learn', W/2-75, H/2+70 + 10 * Math.cos(t));
  ctx.fillText('Grow', W/2-75, H/2+90 + 10 * Math.cos(t));

  ctx.restore();
}
